//! The function samples: every function this build implements, called the way a real
//! spreadsheet calls it, with the answer LibreOffice gives.
//!
//! `tests/data/functions/` holds one flat ODF document per category of Part 4 §6, generated by
//! [odsgen](https://github.com/fwilhe2/odsgen)'s `generate_function_samples.py` and vendored
//! here untouched: a sheet of realistic data — a household budget, a price list, a loan, a
//! staff roster — and a `Samples` sheet with one row per call:
//!
//! | A | B | C | D |
//! |---|---|---|---|
//! | the function | the formula as typed | the formula itself | what it shows |
//!
//! Column C was written with **no cached value** and recalculated by LibreOffice, so the value
//! stored beside each formula is the oracle's answer. The same documents are the samples a
//! person opens to see how a function is used, which is why column B is the formula in the
//! formula bar's own spelling — and checked against it, so the documentation cannot drift.
//!
//! Three properties, each a test:
//!
//! - **Every implemented function has a sample** — adding a function without one fails here.
//! - **Every formula recalculates to the oracle's value**, or is named in [`DIVERGES`] with
//!   the reason this build answers otherwise. Both directions: an entry that starts agreeing
//!   fails too, so the table cannot outlive its reason.
//! - **Column B is what the formula bar shows for column C.**

use std::path::{Path, PathBuf};

use grind_sheet::formula::display;
use grind_sheet::formula::eval::{Address, Engine};
use grind_sheet::formula::funcs;
use grind_sheet::formula::value::{FormulaError, Value};
use grind_sheet::model::{CellValue, Document, Pos};

/// Where this build answers otherwise than the oracle, on purpose: `(file, formula, why)`,
/// the formula as it is stored, without `of:=`.
///
/// Each reason is a line of `doc/ods-format.md` §4.1, where the measurement and the decision
/// are written out; most are "the spec wins".
const DIVERGES: &[(&str, &str, &str)] = &[
    (
        "financial.fods",
        "PPMT([Loan.B4]/12;300;[Loan.B5]*12;-([Loan.B2]-[Loan.B3]))",
        "the oracle's precision: exact arithmetic gives 1435.0827253698145…, this build \
         1435.0827253698142 and the oracle 1435.08272536983",
    ),
    (
        "financial.fods",
        "FV([Loan.B7]/12;10*12;-[Loan.B6])",
        "the oracle's precision: exact 34935.354719083334…, this build 34935.354719083334, \
         the oracle 34935.3547190825",
    ),
    (
        "financial.fods",
        "PV(0.04/12;20*12;-1500)",
        "the oracle's precision: exact 247532.78736525467…, this build 247532.78736525463, \
         the oracle 247532.787365258",
    ),
    (
        "financial.fods",
        "RATE(48;-450;18000)*12",
        "the oracle's iteration stops early: exact 0.0924176698584245…, this build \
         0.09241766985842452, the oracle 0.0924176698588039",
    ),
];

fn dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/functions")
}

/// Every sample document, by file name.
fn documents() -> Vec<(String, Document)> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(dir())
        .map(|entries| entries.flatten().map(|e| e.path()).collect())
        .unwrap_or_default();
    paths.retain(|p| p.extension().is_some_and(|e| e == "fods"));
    paths.sort();
    paths
        .into_iter()
        .map(|path| {
            let name = path.file_name().unwrap().to_string_lossy().into_owned();
            let doc = grind_sheet::read_file(&path)
                .unwrap_or_else(|e| panic!("{name} does not read: {e}"));
            (name, doc)
        })
        .collect()
}

/// Every formula in a document, with where it is: `(sheet index, cell, formula)`.
fn formulas(doc: &Document) -> Vec<(usize, Pos, String)> {
    doc.sheets
        .iter()
        .enumerate()
        .flat_map(|(index, sheet)| {
            sheet
                .formulas()
                .map(move |(pos, formula)| (index, pos, formula.to_owned()))
        })
        .collect()
}

fn a1(pos: Pos) -> String {
    let mut col = String::new();
    let mut c = pos.col + 1;
    while c > 0 {
        col.insert(0, (b'A' + ((c - 1) % 26) as u8) as char);
        c = (c - 1) / 26;
    }
    format!("{col}{}", pos.row + 1)
}

/// The stored formula without its namespace prefix and `=`, the key [`DIVERGES`] uses.
fn bare(formula: &str) -> &str {
    let formula = formula.strip_prefix("of:").unwrap_or(formula);
    formula.strip_prefix('=').unwrap_or(formula)
}

/// Whether a recalculated value is the one the oracle stored. Numbers agree to the fifteen
/// significant digits LibreOffice writes; an error agrees only by name, so the oracle's
/// numbered `Err:5xx` never agrees with anything and every one is a named divergence.
fn agrees(stored: &CellValue, computed: &Value) -> bool {
    match (stored, computed) {
        (CellValue::Number(x), Value::Number(y)) => {
            x == y || (x - y).abs() <= 1e-14 * x.abs().max(y.abs())
        }
        (CellValue::Text(s), Value::Error(e)) => FormulaError::from_name(s) == Some(*e),
        (CellValue::Text(s), Value::Text(t)) => s == t,
        (CellValue::Empty, Value::Text(t)) => t.is_empty(),
        (CellValue::Bool(a), Value::Bool(b)) => a == b,
        (CellValue::Empty, Value::Empty) => true,
        _ => false,
    }
}

#[test]
fn the_samples_are_there() {
    let documents = documents();
    assert!(
        documents.len() >= 10,
        "{} sample documents in {} — the vendoring half failed",
        documents.len(),
        dir().display()
    );
}

#[test]
fn every_implemented_function_has_a_sample() {
    let mut called = std::collections::BTreeSet::new();
    for (_, doc) in documents() {
        for (_, _, formula) in formulas(&doc) {
            called.extend(funcs::used(&formula).unwrap_or_default());
        }
    }
    let missing: Vec<_> = funcs::implemented()
        .into_iter()
        .filter(|name| !called.contains(*name))
        .collect();
    assert!(missing.is_empty(), "no sample calls {missing:?}");
}

#[test]
fn every_sample_recalculates_to_the_oracles_value() {
    let mut failures = Vec::new();
    let mut agreeing = 0;
    let mut reached = std::collections::BTreeSet::new();
    for (file, doc) in documents() {
        let mut engine = Engine::new(&doc);
        for (sheet, pos, formula) in formulas(&doc) {
            let stored = doc.sheets[sheet].get(pos);
            let computed = engine.value(Address::new(sheet, pos));
            let named = DIVERGES
                .iter()
                .find(|(f, text, _)| *f == file && *text == bare(&formula));
            let at = format!("{file} {}.{}", doc.sheets[sheet].name, a1(pos));
            match (agrees(&stored, &computed), named) {
                (true, None) => agreeing += 1,
                (false, Some(_)) => {
                    reached.insert((file.clone(), bare(&formula).to_owned()));
                }
                (true, Some(_)) => failures.push(format!(
                    "{at}: {formula} agrees with the oracle now — delete its DIVERGES entry"
                )),
                (false, None) => failures.push(format!(
                    "{at}: {formula} — the oracle says {stored:?}, this build {computed:?}"
                )),
            }
        }
    }
    for (file, formula, _) in DIVERGES {
        if !reached.contains(&((*file).to_owned(), (*formula).to_owned())) {
            failures.push(format!(
                "DIVERGES names {file}'s {formula}, which no sample holds"
            ));
        }
    }
    eprintln!(
        "function samples: {agreeing} agree with the oracle, {} named divergences",
        DIVERGES.len()
    );
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// Column B of a `Samples` sheet is the documentation: the formula as a person types it.
/// It is held to what the formula bar shows for column C, and column A to a function that
/// formula really calls.
#[test]
fn every_sample_says_what_its_formula_is() {
    let mut failures = Vec::new();
    for (file, doc) in documents() {
        for sheet in doc.sheets.iter().filter(|s| s.name == "Samples") {
            for (pos, formula) in sheet.formulas().filter(|(pos, _)| pos.col == 2) {
                let row = pos.row;
                let at = format!("{file} row {}", row + 1);
                let shown = display::to_display(formula)
                    .unwrap_or_else(|e| panic!("{at}: {formula} does not parse: {e:?}"));
                match sheet.get(Pos::new(row, 1)) {
                    CellValue::Text(typed) if typed == shown => {}
                    other => failures.push(format!("{at}: B says {other:?}, C is {shown}")),
                }
                let named = match sheet.get(Pos::new(row, 0)) {
                    CellValue::Text(name) => name,
                    other => {
                        failures.push(format!("{at}: A names no function: {other:?}"));
                        continue;
                    }
                };
                if !funcs::used(formula)
                    .unwrap_or_default()
                    .contains(&named.to_uppercase())
                {
                    failures.push(format!(
                        "{at}: A says {named}, and {shown} does not call it"
                    ));
                }
            }
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

/// The README beside the documents is the documentation half: a table per category, one row
/// per sample. It is generated with the documents, and checked here so a vendoring that
/// updates one and not the other is caught.
#[test]
fn the_readme_lists_every_function() {
    let readme = std::fs::read_to_string(dir().join("README.md")).expect("the README is vendored");
    let missing: Vec<_> = funcs::implemented()
        .into_iter()
        .filter(|name| !readme.contains(&format!("| `{name}` |")))
        .collect();
    assert!(missing.is_empty(), "the README has no row for {missing:?}");
}
